module parity_8bit (
    input [7:0] in,
    output out
);
    assign out = ^in;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    always @(in or sel) begin
        case(sel)
            2'b00: out = in[0];
            2'b01: out = in[1];
            2'b10: out = in[2];
            2'b11: out = in[3];
        endcase
    end
endmodule

module majority (
    input a, b, c,
    output out
);
assign out = (a & b) | (a & c) | (b & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray = { !binary[3], binary[3] ^ binary[2], binary[2] ^ binary[1], binary[1] ^ binary[0] };
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    assign equal = (a == b);
endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    assign out = 4'b{~in[1], ~in[1] & in[0], in[1] & ~in[0], in[1] & in[0]};
endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);
    //priority encoder output by assigning higher order inputs to output based on priority
    always @(in) begin
        code = 0;
        if (in[3]) code = 2'b11;
        else if (in[2]) code = 2'b10;
        else if (in[1]) code = 2'b01;
        else if (in[0]) code = 2'b00;
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
reg [1:0] state;
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: state <= 2'b01;
            2'b01: state <= 2'b10;
            2'b10: state <= 2'b00;
        endcase
    end
end
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [2:0] light;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            light <= 3'b101;
        end
        else begin
            case (light)
                3'b101: light <= 3'b101;
                3'b011: light <= 3'b110;
                3'b110: light <= 3'b011;
                default: light <= 3'b101;
            endcase
        end
    end
endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    reg [1:0] state, next_state;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
        end
        else begin
            state <= next_state;
        end
    end
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            next_state <= 2'b00;
        end
        else begin
            case (state)
                2'b00: begin
                    if (up_request) next_state <= 2'b01;
                    else if (down_request) next_state <= 2'b10;
                    else next_state <= 2'b00;
                end
                2'b01: begin
                    next_state <= 2'b00;
                end
                2'b10: begin
                    next_state <= 2'b00;
                end
            endcase
        end
    end
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [1:0] state, next_state;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end
    always @(*) begin
        case (state)
            2'b00: next_state = (coin_inserted) ? 2'b01 : 2'b00;
            2'b01: next_state = (item_selected) ? 2'b10 : 2'b01;
            2'b10: next_state = 2'b00;
            default: next_state = 2'b00;
        endcase
    end
endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    assign out = in_0 * in_1;
endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    wire [15:0] d1, d2, d3, d4, d5, d6, d7, d8, d9, d10, d11, d12, d13, d14, d15, d16;

    assign d1 = in_0 - 1;
    assign d2 = (d1 >> 1) - 1;
    assign d3 = (d2 >> 1) - 1;
    assign d4 = (d3 >> 1) - 1;
    assign d5 = (d4 >> 1) - 1;
    assign d6 = (d5 >> 1) - 1;
    assign d7 = (d6 >> 1) - 1;
    assign d8 = (d7 >> 1) - 1;
    assign d9 = (d8 >> 1) - 1;
    assign d10 = (d9 >> 1) - 1;
    assign d11 = (d10 >> 1) - 1;
    assign d12 = (d11 >> 1) - 1;
    assign d13 = (d12 >> 1) - 1;
    assign d14 = (d13 >> 1) - 1;
    assign d15 = (d14 >> 1) - 1;
    assign d16 = (d15 >> 1) - 1;

    assign out = d16 - 1;
endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    assign out = a + b;
endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);
wire [7:0] y0, y1, y2, y3, y4, y5, y6, y7;

assign y0 = a[0] ? b & 1 : 0;
assign y1 = a[1] ? b & 2 : 0;
assign y2 = a[2] ? b & 4 : 0;
assign y3 = a[3] ? b & 8 : 0; 

assign y4 = a[0] ? b & 4 : 0;
assign y5 = a[1] ? b & 8 : 0;
assign y6 = a[2] ? b & 16: 0;
assign y7 = a[3] ? b & 32: 0;

assign out = {y7, y6, y5, y4, y3, y2, y1, y0};
endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    assign diff = a - b;
endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);
    assign and_out = a & b;
    assign or_out = a | b;
    assign xor_out = a ^ b;
endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    assign out = {in[6:0], in[7]};
endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);
    assign out = ~in;
endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    // Rotation is performed by left shifting the value and taking the MSB as the LSB
    assign out = {in[7], in[6:0]};
    // shift is not used in the operation, but the code is written to match the requirement
endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);
    assign out = in_0 > 0 ? in_0 : 0;
endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire [7:0] shifted_data;
    assign shifted_data = data_in + 3;
    assign data_out = shifted_data;
endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    assign data_out = data_in + 8'd1234;
endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key
    wire [7:0] temp;
    assign temp = data_in ^ KEY;
    assign data_out = temp;
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    reg [2:0] count;
    reg [2:0] period = 3'b0;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            period <= 0;
        end else begin
            if (period == 1) begin
                period <= 0;
            end else begin
                period <= period + 1;
                count <= count + 1;
                if (count == 3) begin
                    clk_out <= ~clk_out;
                    count <= 0;
                end
            end
        end
    end
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    assign eq = (a == b);
    assign gt = (a > b);
    assign lt = (a < b);
endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);
    assign out = (enable & (in == 2'b00)) ? 4'b0001 : 
                (enable & (in == 2'b01)) ? 4'b0010 : 
                (enable & (in == 2'b10)) ? 4'b0100 : 
                (enable & (in == 2'b11)) ? 4'b1000 : 4'b0000;
endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);
    // This code is based on the reference of the target circuit, which is a 1-to-2 demultiplexer. 
    // The circuit operates by selecting the output based on the control signal: when the select signal (sel) is low, the input (in) is passed to output 0, and when it is high, the input is passed to output 1.
    assign out0 = (sel) ? 0 : in; // Select 0 when sel is high, else select in.
    assign out1 = (sel) ? in : 0; // Select in when sel is high, else select 0.
endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);
    assign out0 = (sel == 2'b00) ? in : 1'b0;
    assign out1 = (sel == 2'b01) ? in : 1'b0;
    assign out2 = (sel == 2'b10) ? in : 1'b0;
    assign out3 = (sel == 2'b11) ? in : 1'b0;
endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);
    reg [7:0] count;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
        end
        else begin
            count <= {count[7], count[6], count[5], count[4], count[3], count[2], count[1], count[0] ^ 1};
        end
    end
endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);
    reg [3:0] q_reg = 4'b0000;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q_reg <= 4'b0000;
        end else begin
            q_reg <= {q_reg[2:0], ~q_reg[3]};
        end
        assign q = q_reg;
    end
endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);
    reg [7:0] data;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            data <= 0;
        end else if (load) begin
            data <= pin;
        end else begin
            if (sout == 1'b1) begin
                data <= data << 1;
            end
        end
    end
    assign sout = data[0];
endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);
    // Priority encoder for 4 input lines to 2 output lines
    // When the input is active low, the output corresponds to the highest priority input that is active
    assign out = in != 0 ? (in[3] ? 2'b11 : in[2] ? 2'b10 : in[1] ? 2'b01 : 2'b00) : 2'b00;
    assign valid = (in != 0) ? 1 : 0;
endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);
    reg [3:0] counter;
    always @(posedge clk or posedge rst) begin
        if (rst) 
            counter <= 4'b0001;
        else 
            counter <= {counter[2:0], counter[3]};
    end
    assign q = counter;
endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);
    reg [7:0] register;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            register <= 0;
        end else begin
            register <= {register[6:0], sin};
        end
    end
    assign pout = register;
endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);
    reg [7:0] register;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            register <= 8'b0;
        end else begin
            register <= {register[6:0], sin};
        end
    end
    assign sout = register[0];
endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);
reg [7:0] count;
always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end
endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);
  wire [2:0] i0, i1, i2, i3, i4, i5, i6, i7, i8, i9;
  //op1: 0[g3] 1[g2] 2[g1] 3[g0]
  assign i0 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i1 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i2 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i3 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i4 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i5 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i6 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i7 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i8 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  assign i9 = {r, r, r, r, r, r, r, r, r, r, r, r, r, r};
  //not sure if this is correct but follows the pattern from the original question.
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      g <= 3'b0;
    end else begin
      g <= i3;
    end
  end
endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);
  wire v1, v2, v3, v4, v5, v6, v7, v8, v9, v10, v11;

  assign v1 = p1b & p1e & p1f;
  assign v2 = p1a | p1c | p1d;
  assign v3 = p1e & p1a;
  assign v4 = p2b & p2d;
  assign v5 = p1b | p1c | p1d;
  assign v6 = p1a | p1d | p1e;
  assign v7 = p1c & p1e & p1f;
  assign v8 = p1b | p1d | p1f;
  assign v9 = p2a & p2b;
  assign v10 = p2a | p2b | p2c;
  assign v11 = p2a & p2c;
  assign p1y = v1 | v2 | v3 | v4 | v5 | v6 | v7 | v8;
  assign p2y = v9 | v10 | v11;
endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

  wire wire1 = a & b;
  wire wire2 = a | b;
  wire wire3 = wire1 ^ wire2;
  wire wire4 = wire1 ^ b;
  wire wire5 = wire2 ^ b;
  wire wire6 = wire1 & wire2 & wire3 & wire4 & wire5 & wire6;

  assign out_assign = wire6;

  always @(*) begin
    case (a)
      1'b0: out_alwaysblock = 0;
      1'b1: out_alwaysblock = 1;
    endcase
  end

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);
  reg out_always_ff;
  wire w1;
  wire w2;
  assign out_assign = b;
  wire out_1 = a & !b;
  wire out_2 = !a & b;
  wire out_3 = a & b;
  wire out_4 = !a & !b;
  wire w3 = a;
  wire w4 = b;
  out_always_comb = out_1 | out_2;
  out_always_ff <= out_3;
  wire w5 = out_4; 
  w1 = out_3;
  w2 = out_4;
  w3 = w1 | w2;
  w4 = a ^ b;
  w5 = a & b;
  out_always_ff = w3;
endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  assign out_assign = (sel_b1) ? b : a;
  always @(sel_b2) begin
    out_always = (sel_b1) ? b : a;
  end
endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);
  assign shut_off_computer = cpu_overheated;
  assign keep_driving = arrived & !gas_tank_empty;
endmodule

module TopModule (
  input [15:0] scancode,
  output reg left,
  output reg down,
  output reg right,
  output reg up
);

  // Determine arrow direction based on scancode
  always @(*) begin
    case(scancode)
      16'h0000: left = 0; down = 0; right = 0; up = 0;
      16'h0001: left = 0; down = 1; right = 0; up = 0;
      16'h0002: left = 0; down = 0; right = 1; up = 0;
      16'h0004: left = 0; down = 0; right = 0; up = 1;
      16'h0008: left = 1; down = 0; right = 0; up = 0;
      16'h0010: left = 0; down = 1; right = 1; up = 0;
      16'h0020: left = 0; down = 0; right = 1; up = 1;
      16'h0040: left = 1; down = 1; right = 0; up = 0;
      16'h0080: left = 1; down = 0; right = 0; up = 1;
      16'h0100: left = 1; down = 1; right = 1; up = 1;
      default: left = 0; down = 0; right = 0; up = 0;
    endcase
  end

endmodule

module TopModule (
  input a,
  input b,
  output out
);
  assign out = a & b;
endmodule

module TopModule (
  input [7:0] code,
  output reg [3:0] out,
  output reg valid
);

  always @(code) begin
    case(code)
      8'h00: out <= 4'h0; valid <= 1'b0;
      8'h01: out <= 4'h1; valid <= 1'b1;
      8'h02: out <= 4'h2; valid <= 1'b1;
      8'h03: out <= 4'h3; valid <= 1'b1;
      8'h04: out <= 4'h4; valid <= 1'b1;
      8'h05: out <= 4'h5; valid <= 1'b1;
      8'h06: out <= 4'h6; valid <= 1'b1;
      8'h07: out <= 4'h7; valid <= 1'b1;
      8'h08: out <= 4'h8; valid <= 1'b1;
      8'h09: out <= 4'h9; valid <= 1'b1;
      8'h0A: out <= 4'hA; valid <= 1'b1;
      8'h0B: out <= 4'hB; valid <= 1'b1;
      8'h0C: out <= 4'hC; valid <= 1'b1;
      8'h0D: out <= 4'hD; valid <= 1'b1;
      8'h0E: out <= 4'hE; valid <= 1'b1;
      8'h0F: out <= 4'hF; valid <= 1'b1;
      default: out <= 4'h0; valid <= 1'b0;
    endcase
  end

endmodule

module TopModule (
  input a,
  input b,
  output q
);
  assign q = a & b;
endmodule

module TopModule (
  input [2:0] a,
  output reg [15:0] q
);
  always @(*) begin
    case (a)
      3'b000: q = 16'd0;
      3'b001: q = 16'd1;
      3'b010: q = 16'd2;
      3'b011: q = 16'd3;
      3'b100: q = 16'd4;
      3'b101: q = 16'd5;
      3'b110: q = 16'd6;
      3'b111: q = 16'd7;
    endcase
  end
endmodule

module TopModule (
  input clk,
  input a,
  output reg q
);
  always @(posedge clk) begin
    if (a) q <= #5 1'b0;
    else q <= #5 1'b1;
  end
endmodule

