endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);
  logic [1:0] reg_state, next_state;
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      reg_state <= 2'b00;
    end else begin
      reg_state <= next_state;
    end
  end
  always @ (*) begin
    case (reg_state)
      2'b00: begin
        if (train_valid && train_taken) next_state = 2'b01;
        else next_state = 2'b00;
      end
      2'b01: begin
        if ((train_valid && train_taken) || !train_valid) next_state = 2'b00;
        else next_state = 2'b01;
      end
      default: next_state = 2'b00;
    endcase
  end
endmodule

module TopModule (
  input clk,
  input d,
  output reg q
);
  always @(posedge clk) begin
    if (d) q <= 1'b1;
    else q <= 1'b0;
  end
endmodule

module TopModule (
  input clk,
  input j,
  input k,
  output reg Q
);
  always @(posedge clk) begin
    if (k == 1'b1) begin
      Q <= 1'b0;
    end else if (j == 1'b1) begin
      Q <= 1'b1;
    end else begin
      Q <= Q;
    end
  end
endmodule

module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);
  wire [7:0] sum;
  assign sum = a + b;

  assign s = sum;
  assign overflow = (a[7] & b[7]) | (~a[7] & b[7]) | (a[7] & ~b[7]);
endmodule

module TopModule (
  input clk,
  input [7:0] in,
