module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);
  reg [1:0] state, next_state;
  reg [3:0] count;
  reg [1:0] dir;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= 2'b00;
      count <= 4'd0;
      dir <= 2'b00;
    end else begin
      state <= next_state;
      count <= count + 1;
      dir <= next_state;
    end
  end

  always @(*) begin
    case (state)
      2'b00: begin
        if (bump_left) begin
          dir <= 2'b00;
          next_state <= 2'b01;
        end else if (bump_right) begin
          dir <= 2'b10;
          next_state <= 2'b01;
        end else begin
          next_state <= 2'b00;
        end
      end
      2'b01: begin
        if (count > 4'd1) begin
          next_state <= 2'b10;
        end else begin
          if (bump_left) begin
            next_state <= 2'b00;
          end else if (bump_right) begin
            next_state <= 2'b01;
          end
        end
      end
      2'b10: begin
        if (bump_right) begin
          next_state <= 2'b11;
        end else begin
          next_state <= 2'b01;
        end
      end
      2'b11: begin
        if (count > 4'd1) begin
          next_state <= 2'b00;
        end else begin
          if (bump_right) begin
            next_state <= 2'b10;
          end else begin
            next_state <= 2'b01;
          end
        end
      end
      default: next_state <= 2'b00;
    endcase
  end

  assign walk_left = (dir == 2'b00);
  assign walk_right = (dir == 2'b10);
endmodule

