        4'b0000: next_state = (IN == 1) ? 4'b0001 : 4'b0000;
        4'b0001: next_state = (IN == 1) ? 4'b0010 : 4'b0000;
        4'b0010: next_state = (IN == 1) ? 4'b0011 : 4'b0000;
        4'b0011: next_state = (IN == 1) ? 4'b0100 : 4'b0000;
        4'b0100: next_state = (IN == 1) ? 4'b0101 : 4'b0000;
        4'b0101: next_state = (IN == 1) ? 4'b0110 : 4'b0000;
        4'b0110: next_state = (IN == 1) ? 4'b0111 : 4'b0000;
        4'b0111: next_state = (IN == 1) ? 4'b1000 : 4'b0000;
        4'b1000: next_state = (IN == 1) ? 4'b1001 : 4'b0000;
        4'b1001: next_state = (IN == 1) ? 4'b1010 : 4'b0000;
        4'b1010: next_state = (IN == 1) ? 4'b1011 : 4'b0000;
        4'b1011: next_state = (IN == 1) ? 4'b1100 : 4'b0000;
        4'b1100: next_state = (IN == 1) ? 4'b1101 : 4'b0000;
        4'b1101: next_state = (IN == 1) ? 4'b1110 : 4'b0000;
        4'b1110: next_state = (IN == 1) ? 4'b1111 : 4'b0000;
